package foodchain

import "strings"

var animals = []string{
	"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse",
}

var comments = map[int]string{
	1: "It wriggled and jiggled and tickled inside her.",
	2: "How absurd to swallow a bird!",
	3: "Imagine that, to swallow a cat!",
	4: "What a hog, to swallow a dog!",
	5: "Just opened her throat and swallowed a goat!",
	6: "I don't know how she swallowed a cow!",
	7: "She's dead, of course!",
}

const spiderSuffix = " that wriggled and jiggled and tickled inside her"

func Verse(v int) string {
	animal := animals[v-1]
	lines := []string{"I know an old lady who swallowed a " + animal + "."}
	if comment, ok := comments[v]; ok {
		lines = append(lines, comment)
	}
	for i := v - 1; i >= 1; i-- {
		suffix := ""
		if animals[i-1] == "spider" {
			suffix = spiderSuffix
		}
		lines = append(lines, "She swallowed the "+animal+" to catch the "+animals[i-1]+suffix+".")
	}
	if v < 8 {
		lines = append(lines, "I don't know why she swallowed the fly. Perhaps she'll die.")
	}
	return strings.Join(lines, "\n")
}

func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, len(animals))
}

