	}
	for i := v - 1; i >= 1; i-- {
		suffix := ""
		if animals[i-1] == "spider" {
			suffix = spiderSuffix
		}
		lines = append(lines, "She swallowed the "+animals[i]+" to catch the "+animals[i-1]+suffix+".")
	}
	if v < 8 {
		lines = append(lines, "I don't know why she swallowed the fly. Perhaps she'll die.")
	}
	return strings.Join(lines, "\n")
}
```

And the comments map: 2: spider's comment, 3: bird, 4: cat, 5: dog, 6: goat, 7: cow, 8: horse.

